/* TrialAgents Investor Updates 1.0.0 (life.investor-updates) | frontend-js function body. No DOM, network or browser storage.
 * Returns {html,css,state}. Investors (people in categories, optionally linked to firms) receive updates: an email, or a meeting with a
 * before part (agenda and pre-read) and an after part (recap). Claude or ChatGPT drafts the blocks and facts; the app checks facts, keeps
 * the promise tracker, builds one version per category level, gets one- or two-step approval and sends through the TrialAgents external
 * exchange (update rooms, §6 U1–U4): every send is confirmed by a person, reads and responses arrive as tracked records.
 * Every record write is one exact records.propose batch that a person approves; assistants only ever propose and never approve, send,
 * answer a recipient, unsubscribe anyone or see recipient links. Every action is also an app command (appCommands, line 2) that
 * replays the same handler, so Claude and ChatGPT get the same review as a click.
 */

const cfg=typeof templateConfiguration==='object'&&templateConfiguration?templateConfiguration:{};
const bindings=Array.isArray(templateBindings)?templateBindings:[];
const inp=input||{};
let event=inp.event||{kind:'open',action:'',value:null,form:{}};
let action=String(event.action||'');
let form=event.form&&typeof event.form==='object'?event.form:{};
let isAct=event.kind==='click'||event.kind==='submit';

const esc=v=>String(v===null||v===undefined?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const has=(o,k)=>!!o&&Object.prototype.hasOwnProperty.call(o,k);
const num=(v,otherwise=null)=>v!==null&&v!==undefined&&v!==''&&typeof v!=='boolean'&&Number.isFinite(Number(v))?Number(v):otherwise;
const bool=v=>v===true||v==='true'||v==='on'||v==='1';
const onUnlessOff=v=>!(v===false||v==='false');
const MONTHS=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const MONTHS_LONG=['January','February','March','April','May','June','July','August','September','October','November','December'];
const validDate=v=>{const t=String(v||'').slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(t))return '';const d=new Date(t+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===t?t:'';};
const dayNo=d=>Math.round(Date.UTC(Number(d.slice(0,4)),Number(d.slice(5,7))-1,Number(d.slice(8,10)))/86400000);
const addDays=(d,n)=>d?new Date((dayNo(d)+Math.round(n))*86400000).toISOString().slice(0,10):'';
const diffDays=(a,b)=>dayNo(b)-dayNo(a);
const monthEnd=(y,m)=>new Date(Date.UTC(y,m,0)).toISOString().slice(0,10);
const dateLabel=d=>d?Number(d.slice(8,10))+' '+MONTHS[Number(d.slice(5,7))-1]+' '+d.slice(0,4):'—';
const shortDate=d=>d?Number(d.slice(8,10))+' '+MONTHS[Number(d.slice(5,7))-1]:'—';
const plural=(n,w)=>n+' '+(w==='person'?(Math.abs(n)===1?'person':'people'):w+(Math.abs(n)===1?'':'s'));
const label=v=>String(v===null||v===undefined||v===''?'—':v).replace(/_/g,' ');
const cap=s=>{s=label(s);return s.charAt(0).toUpperCase()+s.slice(1);};
const parseJSON=v=>{if(v&&typeof v==='object')return v;try{const x=JSON.parse(String(v||''));return x&&typeof x==='object'?x:null;}catch(e){return null;}};
const arr=v=>{const x=parseJSON(v);return Array.isArray(x)?x:[];};
const ids=v=>arr(v).map(String).filter(Boolean);
const OBJ=v=>{const x=parseJSON(v);return x&&!Array.isArray(x)?x:{};};
const uuid=v=>/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(v||''));
const norm=v=>String(v||'').toLowerCase().replace(/\s+/g,' ').trim();
const textOf=(v,max)=>String(v===null||v===undefined?'':v).trim().slice(0,max||300);
const pct=(a,b)=>b?Math.round(a/b*100)+'%':'—';
const emailOk=v=>/^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]+$/.test(String(v||''));
const lines=v=>String(v||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);

