 if(sub==='classes'){const rows=CLASSES.map(c=>'<tr><td>'+ROWLINK(c.name,'open:class:'+c.id)+'</td><td>'+esc(cap(c.kind))+'</td><td class="num">'+RECIPS.filter(r=>ids(r.share_class_ids).includes(c.id)).length+'</td><td>'+esc(textOf(c.notes,80)||'—')+'</td></tr>');
  return tabs+panel('Share classes','Your list of classes. v1 stores classes only: no amounts, ownership or cap table.',tbl('Share classes',['Class','Kind','Holders','Notes'],rows,'No share classes yet.'),bS('Add share class','add:classes',!WR));}
 const q=norm(st.query),F=st.flt;const xs=RECIPS.filter(r=>(!F.icat||CAT[F.icat]&&inCategory(r,CAT[F.icat]))&&(!F.istatus||r.status===F.istatus)&&(!q||norm(recipName(r)+' '+orgName(recipFirm(r))+' '+recipEmail(r)).includes(q))).sort((a,b)=>recipName(a).localeCompare(recipName(b)));
 const pg=paged(xs),C=cols('investors'),H={person:'Person',firm:'Firm',categories:'Categories',classes:'Share classes',status:'Status',last_read:'Last read',email:'Email'};
 const cell={person:r=>'<td>'+ROWLINK(recipName(r),'open:recipient:'+r.id)+'</td>',firm:r=>'<td>'+esc(recipFirm(r)?orgName(recipFirm(r)):'—')+'</td>',categories:r=>'<td>'+esc(catsOfRecipient(r).map(catName).join(', ')||'—')+'</td>',classes:r=>'<td>'+esc(ids(r.share_class_ids).map(id=>CLASS[id]?CLASS[id].name:'—').join(', ')||'—')+'</td>',status:r=>'<td>'+pill(r.status==='paused'?'Paused':'Receives',r.status)+'</td>',last_read:r=>{const d=DELIV.filter(x=>x.recipient_id===r.id&&validDate(x.last_read_on)).map(x=>x.last_read_on).sort().slice(-1)[0];return '<td>'+esc(d?shortDate(d):'—')+'</td>';},email:r=>'<td>'+esc(recipEmail(r)||'No email')+'</td>'};
 const pending=st.f.investor&&st.f.investor.person_hint?PEOPLE.find(p=>norm(p.email)===norm(st.f.investor.person_hint)||norm(p.name)===norm(st.f.investor.person_hint)):null;
