 const texts=formWrap('texts','save-texts',TEXT_KEYS.map(k=>{const t=textsFor(k);return '<fieldset class="iu-fieldset"><legend>'+esc({update:'Email update',meeting_before:'Meeting, before',meeting_after:'Meeting, after',answer:'Answer to a question',reminder:'Not-read reminder'}[k])+'</legend>'+field('texts',k+'_subject','Subject',t.subject,'text',{wide:true})+area('texts',k+'_body','Text before the update',t.body,{rows:3})+'</fieldset>';}).join('')+'<p class="iu-muted">Placeholders: {recipient_name} {recipient_company} {sender_name} {sender_company} {title} {link} {message}. Every send shows each email exactly as it will go out before a person confirms it.</p>','Save email texts');
